#include <stdio.h>

int main(void) {
    long long x;
    scanf("%lld", &x);
    const unsigned char *bytes = (const unsigned char *)&x;
    int count = 0;
    for (size_t i = 0; i < sizeof x; i++) {
        unsigned char v = bytes[i];
        for (int b = 0; b < 8; b++) {
            count += (v >> b) & 1;
        }
    }
    printf("%d\n", count);
    return 0;
}

