#include <stdio.h>

int main(void) {
    double a, b;
    scanf("%lf %lf", &a, &b);
    const unsigned char *pa = (const unsigned char *)&a;
    const unsigned char *pb = (const unsigned char *)&b;
    int same_bytes = 1;
    for (size_t i = 0; i < sizeof a; i++) {
        if (pa[i] != pb[i]) {
            same_bytes = 0;
        }
    }
    printf("values: %s\n", a == b ? "equal" : "different");
    printf("bytes: %s\n", same_bytes ? "equal" : "different");
    return 0;
}

